// src/core/result-envelope.ts
var readUserActionSurface = ({
  store,
  rootId
}) => ({
  conflicts: store.readConflicts(rootId).filter((conflict) => conflict.state === "open"),
  guards: store.readGuardBlocks(rootId),
  tombstones: store.readTombstones(rootId),
  outbox: store.readOutbox(rootId).filter((command) => command.state !== "settled")
});

// src/core/status.ts
var latestBinding = ({
  store,
  rootId
}) => {
  let binding;
  for (const event of store.replay(rootId)) {
    if (event._tag === "SyncBindingRecorded") {
      binding = event;
    }
  }
  return binding?._tag === "SyncBindingRecorded" ? {
    dataSourceId: binding.dataSourceId,
    workspaceRoot: binding.workspaceRoot,
    storeIdentity: binding.storeIdentity
  } : undefined;
};
var readOneShotSyncStatus = ({
  store,
  rootId
}) => {
  const projection = store.readStatusProjection(rootId);
  const pending = projection.outbox.queued + projection.outbox.running + projection.outbox.retryable;
  const conflict = projection.conflicts.open;
  const blocked3 = projection.outbox.blocked + projection.outbox.fenced + projection.outbox.ambiguous + projection.tombstones.unclassified + projection.guards.blocked + projection.capabilities.unsupported + projection.checkpoints.incompleteQueries + projection.checkpoints.cappedQueries + projection.checkpoints.changedQueryContracts;
  const state = conflict > 0 ? "conflict" : blocked3 > 0 ? "blocked" : pending > 0 ? "pending" : "clean";
  return {
    rootId,
    binding: latestBinding({ store, rootId }),
    state,
    counts: {
      clean: state === "clean" ? 1 : 0,
      pending,
      conflict,
      blocked: blocked3,
      outbox: projection.outbox,
      projections: projection.projections,
      tombstones: projection.tombstones,
      guards: projection.guards,
      capabilities: projection.capabilities,
      checkpoints: projection.checkpoints
    }
  };
};

